 // Receber o CSV do nó HTTP Request
const csvRaw = $input.first().json.data;

if (typeof csvRaw !== "string") {
  throw new Error("O HTTP Request deve retornar o CSV como texto no campo data.");
}

// Separar as linhas do CSV
const lines = csvRaw
  .replace(/^\uFEFF/, "")
  .split(/\r?\n/)
  .map(l => l.trim())
  .filter(Boolean);

// Identificar o cabeçalho (separado por vírgulas)
const headers = lines[0]
  .split(",")
  .map(h => h.trim());

// Converter as linhas em objetos JSON
const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());

  const obj = {};

  headers.forEach((h, i) => {
    obj[h] = cols[i] ?? "";
  });

  // Converter o investimento mínimo em número
  obj.minimo = Number(obj.minimo) || 0;

  return obj;
});

// Devolver a lista de investimentos
return [{ json: { investimentos } }];

const clientes = $('Cadastro Clientes').first().json.body?.clientes;

const investimentos = $('Normalizando').first().json.investimentos;

// Verificar se as duas listas foram recebidas
if (!Array.isArray(clientes) || !Array.isArray(investimentos)) {
  throw new Error(
    'Não encontrei os clientes do Webhook ou os investimentos do primeiro Code.'
  );
}

// Formatação de valores em reais
const dinheiro = new Intl.NumberFormat('pt-BR', {
  style: 'currency',
  currency: 'BRL'
});

// Converter valores como "R$ 12.500,00" em 12500
function paraNumero(valor) {
  if (typeof valor === 'number') return valor;

  const texto = String(valor ?? '')
    .replace(/R\$/gi, '')
    .replace(/\s/g, '');

  return texto.includes(',')
    ? Number(texto.replace(/\./g, '').replace(',', '.'))
    : Number(texto.replace(/[^\d.-]/g, ''));
}

// Padronizar os perfis
function normalizar(valor) {
  return String(valor ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();
}

// Criar uma mensagem personalizada para cada cliente
const mensagens = clientes.map(cliente => {

  const nome = String(cliente.nome ?? 'Cliente').trim();
  const primeiroNome = nome.split(/\s+/)[0];
  const email = String(cliente.email ?? '').trim();
  const perfil = String(cliente.perfil ?? '').trim();
  const saldo = paraNumero(cliente.saldo);

  if (!Number.isFinite(saldo)) {
    throw new Error(`Saldo inválido para ${nome}`);
  }

  // Buscar investimentos compatíveis com perfil e saldo
  const compativeis = investimentos
    .filter(inv =>
      normalizar(inv.perfil) === normalizar(perfil) &&
      paraNumero(inv.minimo) <= saldo
    )
    .sort((a, b) =>
      paraNumero(a.minimo) - paraNumero(b.minimo)
    );

  const linhas = compativeis.map((inv, i) =>
    `${i + 1}. ${inv.produto} — aplicação mínima: ` +
    `${dinheiro.format(paraNumero(inv.minimo))}; ` +
    `rentabilidade informada no CSV: ` +
    `${inv.rentabilidade || 'não informada'}.`
  );

  let conteudo;

  if (compativeis.length > 0) {
    conteudo =
      `Considerando seu perfil ${perfil} e seu saldo de ` +
      `${dinheiro.format(saldo)}, identificamos as seguintes ` +
      `opções do catálogo compatíveis com seus dados:\n\n` +
      linhas.join('\n');
  } else {
    conteudo =
      `Considerando seu perfil ${perfil} e seu saldo de ` +
      `${dinheiro.format(saldo)}, não encontramos produtos ` +
      `no catálogo que atendam ao investimento mínimo.`;
  }

  const mensagem =
    `Olá, ${primeiroNome}!\n\n` +
    conteudo +
    `\n\nEstas informações são ilustrativas e fazem parte ` +
    `de um exercício educacional. Não constituem ` +
    `recomendação financeira individual, e as ` +
    `rentabilidades apresentadas não são garantidas.`;

  return {
    nome,
    email,
    perfil,
    saldo,
    mensagem
  };
});

// Retornar todas as mensagens em um único JSON
return [{
  json: {
    total_clientes: clientes.length,
    total_mensagens: mensagens.length,
    mensagens
  }
}];

/*
 * PREPARAÇÃO DOS DADOS PARA INTELIGÊNCIA ARTIFICIAL
 * Entrada: mensagens geradas pelo Code anterior
 * Saída: uma linha por cliente
 */

// 1. Recuperar as mensagens do nó anterior
const entrada = $input.first().json;

if (!Array.isArray(entrada.mensagens)) {
  throw new Error(
    "Não foi encontrada a lista de mensagens do nó anterior."
  );
}

// 2. Limpar textos
function limparTexto(valor) {
  return String(valor ?? "")
    .replace(/\s+/g, " ")
    .trim();
}

// 3. Organizar os clientes em registros individuais
const resultado = entrada.mensagens.map((cliente, indice) => {

  const nome = limparTexto(cliente.nome);
  const email = limparTexto(cliente.email).toLowerCase();
  const perfil = limparTexto(cliente.perfil);
  const saldo = Number(cliente.saldo);
  const mensagem = String(cliente.mensagem ?? "")
    .replace(/\r\n/g, "\n")
    .trim();

  // 4. Validar informações
  if (!nome || !email || !perfil || !Number.isFinite(saldo)) {
    throw new Error(
      `Dados inválidos no cliente ${indice + 1}`
    );
  }

  // 5. Criar instrução para a futura IA
  const promptIA = `
Atue como um assistente de comunicação financeira.

Revise a mensagem destinada ao cliente, tornando-a
clara, profissional, cordial e personalizada.

Regras:
- Preserve o perfil e os valores informados.
- Não invente investimentos nem rentabilidades.
- Não prometa resultados financeiros.
- Não apresente recomendações financeiras individuais.
- Preserve o aviso de finalidade educacional.
- Responda somente com a mensagem revisada.

Nome: ${nome}
Perfil: ${perfil}
Saldo disponível: R$ ${saldo.toFixed(2)}

Mensagem original:
${mensagem}
`.trim();

  // 6. Retornar uma linha da tabela
  return {
    json: {
      id_cliente: indice + 1,
      nome: nome,
      email: email,
      perfil: perfil,
      saldo: saldo,
      mensagem: mensagem,
      prompt_ia: promptIA,
      status: "Pronto para IA"
    },
    pairedItem: {
      item: 0
    }
  };
});

// 7. Entregar os registros ao próximo nó
return resultado;

/*
 * NORMALIZAÇÃO DE E-MAILS PARA GMAIL
 * Fluxo: Prep. IA -> Gemini -> Code
 */

const itens = $input.all();

// 1. Localizar o texto da resposta do Gemini
function localizarTexto(valor, nivel = 0) {
  if (nivel > 6 || valor == null) return "";

  if (typeof valor === "string") return valor;

  if (Array.isArray(valor)) {
    for (const parte of valor) {
      const texto = localizarTexto(parte, nivel + 1);
      if (texto) return texto;
    }
    return "";
  }

  if (typeof valor === "object") {
    const campos = [
      "text", "parts", "content", "candidates",
      "output", "response", "message", "data"
    ];

    for (const campo of campos) {
      if (valor[campo] != null) {
        const texto = localizarTexto(valor[campo], nivel + 1);
        if (texto) return texto;
      }
    }
  }

  return "";
}

// 2. Interpretar o conteúdo gerado pela IA
function interpretarResposta(dados) {

  if (dados.assunto || dados.corpo) {
    return dados;
  }

  let texto = localizarTexto(dados).trim();

  if (!texto) {
    throw new Error("Resposta vazia do Gemini.");
  }

  // Remover blocos Markdown
  texto = texto
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  // Tentar converter a resposta em JSON
  try {
    return JSON.parse(texto);
  } catch (erro) {

    // Caso o Gemini retorne Assunto e Corpo em texto
    const assunto = texto.match(/^Assunto:\s*(.+)$/im);
    const corpo = texto.match(/^Corpo:\s*([\s\S]*)$/im);

    if (assunto && corpo) {
      return {
        assunto: assunto[1].trim(),
        corpo: corpo[1].trim()
      };
    }

    // Caso retorne somente texto
    return {
      assunto: "",
      corpo: texto
    };
  }
}

// 3. Preparar os e-mails individualmente
const emails = itens.map((item, indice) => {

  // Nome real do nó anterior ao Gemini
  const cliente = $('Prep. IA')
    .itemMatching(indice).json;

  const respostaIA = interpretarResposta(item.json);

  const nome = String(cliente.nome || "").trim();

  // Sempre recuperar o e-mail dos dados originais
  const para = String(cliente.email || "")
    .trim()
    .toLowerCase();

  // Assunto padronizado
  const assunto = String(
    respostaIA.assunto ||
    respostaIA.subject ||
    `Informações de investimentos para ${nome}`
  )
    .replace(/[\r\n]+/g, " ")
    .trim();

  // Corpo do e-mail
  const corpo = String(
    respostaIA.corpo ||
    respostaIA.body ||
    ""
  )
    .replace(/\r\n/g, "\n")
    .trim();

  // Validar o e-mail
  const emailValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (!emailValido.test(para)) {
    throw new Error(
      `E-mail inválido para ${nome}: ${para}`
    );
  }

  if (!corpo) {
    throw new Error(
      `Corpo do e-mail vazio para ${nome}`
    );
  }

  // 4. Retornar os dados padronizados para Gmail
  return {
    json: {
      nome: nome,
      para: para,
      assunto: assunto,
      corpo: corpo,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      status: "Aguardando revisão"
    },
    pairedItem: {
      item: indice
    }
  };

});

return emails;
